(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.LogarithmLesson,num=window.LinearLesson,ns='http://www.w3.org/2000/svg';
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fraction(q){return num.fractionTex(num.rational(q.n,q.d));}
function baseTex(key){const b=core.bases[key];return b.d===1?String(b.n):`\\left(${fraction(b)}\\right)`;}
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);}
function tick(n,left,top){const e=document.createElement('span');e.className='transform-tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=left+'%';e.style.top=top+'%';$('#log-ticks').append(e);}
for(let n=-5;n<=5;n++){const p=core.point(n,n);svg('line',{x1:p.x,x2:p.x,y1:30,y2:330},$('#log-grid'));svg('line',{x1:30,x2:330,y1:p.y,y2:p.y},$('#log-grid'));tick(n,p.x/3.6,53);if(n!==0)tick(n,47,p.y/3.6);}
function draw(){const key=$('[name="log-base"]:checked').value,t=Number($('#log-power').value),q=core.exactPower(key,t),y=q.n/q.d,b=core.bases[key];$('#log-power-output').value=t;math($('#power-equation'),`${baseTex(key)}^{${t}}=${fraction(q)}`);math($('#log-equation'),`\\log_{${fraction(b)}}\\left(${fraction(q)}\\right)=${t}`);math($('#inverse-pairs'),`(${t},${fraction(q)})\\longleftrightarrow(${fraction(q)},${t})`);const expo=[],log=[];for(let i=0;i<=600;i++){const x=-5+i/60,p=core.point(x,core.power(key,x));expo.push(`${i===0?'M':'L'}${p.x} ${p.y}`);const u=.001+4.999*i/600,r=core.point(u,core.logarithm(key,u));log.push(`${i===0?'M':'L'}${r.x} ${r.y}`);}$('#exponential-curve').setAttribute('d',expo.join(' '));$('#logarithm-curve').setAttribute('d',log.join(' '));$('#log-dots').replaceChildren();for(const [x,z,color] of [[t,y,'#7d6591'],[y,t,'#b4754f']]){const p=core.point(x,z);svg('circle',{cx:p.x,cy:p.y,r:4,fill:color,stroke:'white','stroke-width':1},$('#log-dots'));}$('#log-feedback').textContent=(b.n>b.d?'Basis lebih dari satu: kedua fungsi meningkat.':'Basis positif kurang dari satu: kedua fungsi menurun.')+' Logaritma mengembalikan hasil eksponensial menjadi pangkat semula. '+(y>5?'Pasangan titik terpilih berada di luar jendela grafik; koordinatnya tetap ditampilkan di atas.':'Kedua titik terpilih berkoordinat terbalik dan merupakan pencerminan terhadap garis diagonal abu-abu.');$('#log-plot').setAttribute('aria-label',`Grafik logaritma dan eksponensial basis ${b.n} dibagi ${b.d}. Titik eksponensial (${t}, ${y}) berpasangan dengan titik logaritma (${y}, ${t}).`);$('#argument-feedback').replaceChildren();}
$('#log-power').addEventListener('input',draw);document.querySelectorAll('[name="log-base"]').forEach(e=>e.addEventListener('change',draw));$('#reset-log').addEventListener('click',()=>{$('[name="log-base"][value="two"]').checked=true;$('#log-power').value=2;$('#argument-value').value='0';draw();});draw();
$('#argument-test').addEventListener('submit',e=>{e.preventDefault();const q=num.parseAnswer($('#argument-value').value),host=$('#argument-feedback'),key=$('[name="log-base"]:checked').value,b=core.bases[key];if(!q){host.textContent='Tulis satu bilangan, misalnya 2 atau 1/2.';host.className='feedback incorrect';return;}if(q.n<=0){host.textContent='Argumen ini tidak diperbolehkan untuk logaritma real. Pangkat real dari basis positif tidak menghasilkan nol atau bilangan negatif.';host.className='feedback incorrect';return;}const value=core.logarithm(key,q.n/q.d),integer=Number.isInteger(value),result=integer?String(value):value.toFixed(3).replace('.','{,}');host.className='feedback correct';host.replaceChildren(document.createTextNode(integer?'Argumen ini sah. ':'Argumen ini sah; nilai berikut dibulatkan sampai tiga angka desimal. '));const span=document.createElement('span');span.dataset.tex=`\\log_{${fraction(b)}}\\left(${fraction(q)}\\right)${integer?'=':'\\approx'}${result}`;host.append(span);});
const questions=[{tex:'\\log_2\\frac18',prompt:'Berapa nilainya?',n:-3,d:1,hint:'Cari pangkat dua yang menghasilkan seperdelapan.',why:'Dua berpangkat negatif tiga sama dengan seperdelapan, sehingga hasil logaritmanya negatif tiga.'},{tex:'\\log_4 2',prompt:'Berapa nilainya?',n:1,d:2,hint:'Akar kuadrat empat sama dengan dua.',why:'Empat berpangkat setengah sama dengan dua, sehingga logaritmanya setengah.'},{tex:'\\log_2(x-1)=3',prompt:'Tentukan nilai masukan yang memenuhi persamaan.',n:9,d:1,hint:'Syaratnya masukan lebih besar dari satu. Ubah logaritma menjadi bentuk pangkat.',why:'Masukan dikurangi satu sama dengan delapan, jadi masukannya sembilan. Nilai ini memenuhi domain awal.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya -3 atau 1/2.':'Belum tepat. Ubah pertanyaan logaritma menjadi pertanyaan pangkat, lalu periksa domainnya.');}));
const choices=[{tex:'f(x)=\\log_2(x-3)',prompt:'Apa domain real terbesar fungsi ini?',options:['Semua masukan positif.','Masukan lebih besar dari tiga.','Masukan lebih besar dari atau sama dengan tiga.'],answer:1,why:'Seluruh argumen, yaitu masukan dikurangi tiga, harus positif. Masukan tiga memberi argumen nol dan tidak diperbolehkan.'},{tex:'\\log_b(MN),\\quad M>0,\\ N>0',prompt:'Dengan basis positif bukan satu, bentuk mana yang setara?',options:['Jumlah logaritma kedua argumen dengan basis yang sama.','Hasil kali logaritma kedua argumen.','Logaritma argumen pertama ditambah argumen kedua tanpa logaritma.'],answer:0,why:'Hasil kali argumen menjadi penjumlahan pangkat. Kedua argumen harus positif dan basisnya sama.'},{tex:'f(x)=\\log_{1/2}x',prompt:'Pernyataan mana yang benar?',options:['Argumennya boleh negatif karena basisnya pecahan.','Fungsinya meningkat karena basisnya positif.','Fungsinya menurun pada domain bilangan positif, dan range-nya semua bilangan real.'],answer:2,why:'Basis setengah berada antara nol dan satu, sehingga logaritma menurun. Argumen tetap harus positif; hasilnya boleh real apa pun.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-logarithm-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-logarithm-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();